yakit.AutoInitYakit()

CEYE_API_TOKEN = cli.String("API_TOKEN")
ROOT_DNS = cli.String("ROOT_DNS")

cli.check()

if CEYE_API_TOKEN == "" {
    CEYE_API_TOKEN = env.Get("CEYE_API_TOKEN")
}
if ROOT_DNS == "" {
    ROOT_DNS = env.Get("CEYE_ROOT_DNS")
}

if CEYE_API_TOKEN == "" {
    yakit.Error("请通过设置临时参数 或者通过配置环境变量(CEYE_API_TOKEN)来设置密钥!")
}

rsp, err = http.Request("GET", "http://test." + ROOT_DNS)
die(err)

requireDomain = func() {
    packet = f`GET /v1/records?token=${CEYE_API_TOKEN}&type=dns HTTP/1.1
Host: api.ceye.io

`
        rsp,req = poc.HTTPEx(
            packet,
            poc.https(false),
            poc.timeout(10),
            // poc.proxy("http://127.0.0.1:9999")

        )~
        _, body = poc.Split(rsp.RawPacket)
        subdomain, token = "", CEYE_API_TOKEN
        if len(body)> 0 {
            bs = json.loads(body)
            if bs["meta"]["code"] == 200 {
                record = bs["data"][0]["name"]
                record = record.Lower()
                subdomain = re.Find(record, `\w*\.ceye\.io`)
            }
        }
        return subdomain,token
}

getResults = func(token) {
    packet = f`GET /v1/records?token=${token}&type=dns HTTP/1.1
Host: api.ceye.io
`
    rsp,req = poc.HTTPEx(
            packet,
            poc.https(false),
            poc.timeout(10),
            // poc.proxy("http://127.0.0.1:9999")
        )~
    _, body = poc.Split(rsp.RawPacket)
    events = []
    if len(body)> 0 {
        yakit.Info(json.dumps(body))
        eventMap = json.loads(body)
        // dump(eventMap)
        if eventMap["meta"]["code"] == 200 {
            for _,event :=range eventMap["data"] {
                ts = datetimeToTimestamp(event["created_at"])~
                events = append(events, {
                        "Type": "A",
                        "Domain":     event["name"],
                        "RemoteIP":   event["remote_addr"],
                        // "Raw":        event,
                        "Timestamp": ts,
                        // "Mode" : "custom"
                    }
                )
            }
        }
        return events
    } else {
        yakit.Warn("没有获取到信息，没有记录或者配置密钥错误")
    }

}
